'use client';
import {useEffect,useRef,useState} from 'react';
import {ThemeProvider,createTheme,CssBaseline,Button} from '@mui/material';
import {Documents} from '@/components/Documents';
import KanbanBoard from '@/components/KanbanBoard';
import type {Task,TaskState} from '@/lib/types';
const owner='11111111-1111-4111-8111-111111111111',id='44444444-4444-4444-8444-444444444444';
const project={id:'77777777-7777-4777-8777-777777777777',owner_id:owner,name:'Proyecto de prueba',objective:'Revisión aislada',status:'active' as const,version:1,created_at:'2026-11-19T12:00:00Z',updated_at:'2026-11-19T12:00:00Z'};
const fixture={id,owner_id:owner,project_id:project.id,title:'Propuesta de trabajo',kind:'proposal',version:1,content_json:null,content_md:'## Contexto y objetivos\n\nUn documento para trabajar con **claridad** y contexto.',created_at:'2026-11-19T12:00:00Z',updated_at:'2026-11-19T12:00:00Z'};
export default function Review(){
 const [mode,setMode]=useState<'light'|'dark'>('light'),[view,setView]=useState('documents'),[ready,setReady]=useState(false);
 const record=useRef<any>(fixture),[tasks,setTasks]=useState<Task[]>([{...project,id:'88888888-8888-4888-8888-888888888888',title:'Revisar propuesta',description:'',status:'todo',project_id:project.id,importance:'medium',start_date:null,due_date:null}]);
 useEffect(()=>{const saved=localStorage.getItem('deer-interface-fixture');if(saved)record.current=JSON.parse(saved);setReady(true);},[]);
 async function api(path:string,body?:any){if(body){if(body.expected_version!==record.current.version)throw Error('DEER_VERSION_CONFLICT');record.current={...record.current,...body.payload,version:record.current.version+1,updated_at:new Date().toISOString()};localStorage.setItem('deer-interface-fixture',JSON.stringify(record.current));return {row:record.current};}if(path.includes('kind=documents'))return {rows:[record.current],count:1};if(path.includes('kind=document&'))return {row:record.current};if(path.includes('kind=entity-index'))return {rows:[]};if(path.includes('kind=assets')){const rows=[];for(const [file,name,mime,assetId] of [['png','Imagen de prueba.png','image/png','55555555-5555-4555-8555-555555555555'],['pdf','Archivo de prueba.pdf','application/pdf','66666666-6666-4666-8666-666666666666']]){const data=await (await fetch('/__review.'+file)).arrayBuffer();const sha256=Array.from(new Uint8Array(await crypto.subtle.digest('SHA-256',data))).map(v=>v.toString(16).padStart(2,'0')).join('');rows.push({id:assetId,document_id:id,name,mime_type:mime,size_bytes:data.byteLength,sha256,storage_path:owner+'/'+assetId});}return {rows};}return {rows:[]};}
 return <ThemeProvider theme={createTheme({palette:{mode,primary:{main:mode==='light'?'#4228D3':'#B7A6FF'},background:{default:mode==='light'?'#F6F7FB':'#0D1026',paper:mode==='light'?'#fff':'#191B35'}},typography:{fontFamily:'Manrope,system-ui,sans-serif',button:{textTransform:'none'}}})}><CssBaseline/><div className={'deer '+mode} style={{padding:32}}><header style={{display:'flex',gap:12,marginBottom:20}}><Button onClick={()=>setMode(mode==='light'?'dark':'light')}>Cambiar tema</Button><Button onClick={()=>setView(view==='documents'?'kanban':'documents')}>Cambiar vista de prueba</Button><small>Revisión aislada. No conecta con tus datos.</small></header>{!ready?'Preparando…':view==='documents'?<Documents ownerId={owner} projects={[project]} api={api} demo={false} onDirty={()=>{}} onNavigate={()=>{}}/>:<KanbanBoard tasks={tasks} filter="all" disabled={false} projectName={()=>project.name} onOpen={()=>{}} onMove={async(task,status:TaskState)=>{setTasks(list=>list.map(t=>t.id===task.id?{...t,status,version:t.version+1}:t));}}/>}</div></ThemeProvider>;
}
